#!/usr/bin/env bash
# Sécurité : dépendances à jour, et une garde contre deux copies de Next.
# - Next 16.4.6 (faille critique corrigée), sharp 0.35, nodemailer 10 (ses types sont inclus : @types/nodemailer retiré),
#   Tiptap 3.34, zod 4.6, mailparser 3.14, imapflow 2.11, mammoth 1.13 ; happy-dom 21 déclaré par le web ;
#   sous-dépendances rafraîchies (js-yaml, xmldom, brace-expansion…) ;
# - deux ajustements de code (types de sharp et de nodemailer ; mergeAttributes pris dans @tiptap/core) ;
# - garde check-next-unique.mjs (dans pnpm check) ; doc à jour. Relance pnpm install (réseau). Pas de migration.
# ARRÊTE pnpm dev avant. Prérequis : apply-inscriptions-cours-ecrans.sh.
# Usage (racine du repo) : bash apply-securite-dependances.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"package.json" 2>/dev/null | grep -qF "check-next-unique"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "CoursesControl" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" 2>/dev/null || { echo "lancez d'abord apply-inscriptions-cours-ecrans.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/auth/le-mot-de-passe-oublie.mdx" "apps/web/content/docs/dev/contenu/le-texte-riche.mdx" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" "apps/web/package.json" "apps/web/src/features/editor-tiptap/node/horizontal-rule-node/horizontal-rule-node-extension.ts" "package.json" "packages/backend/package.json" "packages/backend/src/email/templates/welcomeEmailWithPassword.ts" "packages/backend/src/modules/media/services/mediaDerivatives.service.ts" "packages/contracts/package.json" "pnpm-lock.yaml")
CREATED=("scripts/check-next-unique.mjs")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "check-next-unique" "package.json" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "scripts"
base64 -d > "scripts/check-next-unique.mjs" <<'B64'
